begin;
select plan(17);
insert into chats(id) values('6e000000-0000-4000-8000-000000000001');
insert into chat_members(chat_id,user_id,learning_language) values
('6e000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-00000000000a','de'),
('6e000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-00000000000b','en');
insert into chat_message_transports(chat_id,provider,migration_state) values('6e000000-0000-4000-8000-000000000001','stream','active');
create temp table stream_snapshots as select jsonb_build_object('id','6e000000-0000-4000-8000-000000000002','cid','blab:6e000000-0000-4000-8000-000000000001','user',jsonb_build_object('id','00000000-0000-4000-8000-00000000000a'),'type','regular','text','Hello','created_at',now()+interval '1 second','updated_at',now()+interval '1 second','attachments','[]'::jsonb) as original;
grant select,update on stream_snapshots to service_role;
select ok(not has_function_privilege('authenticated','apply_stream_message_snapshot(uuid,jsonb)','execute'),'projection completion is server-only');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
select is(apply_stream_message_snapshot('6e000000-0000-4000-8000-000000000001',(select original from stream_snapshots)),'applied','canonical message creates learning source');
select is(apply_stream_message_snapshot('6e000000-0000-4000-8000-000000000001',(select original from stream_snapshots)),'unchanged','replay cannot duplicate source work');
reset role;
select is((select body from messages where id='6e000000-0000-4000-8000-000000000002'),'Hello','authored text is preserved');
select is((select count(*) from push_notification_events where source_key='6e000000-0000-4000-8000-000000000002'),0::bigint,'learning projection does not duplicate Stream notification');
select ok(exists(select 1 from message_preparation_jobs where message_id='6e000000-0000-4000-8000-000000000002'),'projection starts existing private translation preparation');
set local role service_role;
select is(apply_stream_message_snapshot('6e000000-0000-4000-8000-000000000001',(select original || jsonb_build_object('text','Edited hello','updated_at',now()+interval '2 seconds','message_text_updated_at',now()+interval '2 seconds') from stream_snapshots)),'applied','newer edit is reconciled');
select is(apply_stream_message_snapshot('6e000000-0000-4000-8000-000000000001',(select original from stream_snapshots)),'stale','late original cannot revert newer edit');
select is(apply_stream_message_snapshot('6e000000-0000-4000-8000-000000000001',(select original || jsonb_build_object('text','Edited hello','type','deleted','updated_at',now()+interval '3 seconds','message_text_updated_at',now()+interval '2 seconds','deleted_at',now()+interval '3 seconds') from stream_snapshots)),'applied','canonical soft deletion is reconciled');
reset role;
select is((select count(*) from message_preparation_jobs where message_id='6e000000-0000-4000-8000-000000000002'),0::bigint,'deleted source cannot leave private preparation active');
select is((select body from messages where id='6e000000-0000-4000-8000-000000000002'),'','deleted vendor placeholders never enter retained authored text');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-00000000000a","role":"authenticated"}',true);
set local role authenticated;
select throws_ok($$update messages set body='Client second history' where id='6e000000-0000-4000-8000-000000000002'$$,'P0001','stream_message_server_owned','client cannot edit derived learning history');
reset role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
select is(apply_stream_message_snapshot('6e000000-0000-4000-8000-000000000001',(select original || jsonb_build_object('text','Edited hello','updated_at',now()+interval '4 seconds','message_text_updated_at',now()+interval '2 seconds') from stream_snapshots)),'applied','newer canonical restore revives source');
select throws_ok($$select apply_stream_message_snapshot('6e000000-0000-4000-8000-000000000001',(select original || jsonb_build_object('cid','blab:6e000000-0000-4000-8000-000000000009') from stream_snapshots))$$,'P0001','invalid_stream_snapshot','cross-chat snapshot cannot contaminate learning source');
select is(apply_stream_message_snapshot('6e000000-0000-4000-8000-000000000001',(select original || jsonb_build_object('id','6e000000-0000-4000-8000-000000000003','updated_at',now()+interval '5 seconds','blab_legacy_edited_at',now()+interval '2 seconds') from stream_snapshots)),'applied','imported historical edit timestamp is accepted without a new edit event');
select is((select edited_at from messages where id='6e000000-0000-4000-8000-000000000003'),now()+interval '2 seconds','historical edit survives background projection');
select is(apply_stream_message_snapshot('6e000000-0000-4000-8000-000000000001',(select original || jsonb_build_object('id','6e000000-0000-4000-8000-000000000003','updated_at',now()+interval '6 seconds','blab_legacy_edited_at',now()+interval '2 seconds') from stream_snapshots)),'applied','metadata-only arrival retains historical edit time');
reset role;
select * from finish();
rollback;
